# Code generated by Claude
"""
The robot at rest on the imported model: contacts, lean and the clearances that changed with the new pedestal.

    MUJOCO_GL=egl python experiments/rest_contacts_test.py

The robot (neck, battery, face off, both arms at the start pose, grippers open) stands on the floor of the lab scene, the base held still, for 3 s at each of two pedestal heights (raised: the model's start;
the staging height TASK_CFG["pedestal_q"]). Reported and checked:
  1. Contacts: only the floor with the six base spheres; nothing robot-to-robot (every other contact listed with its depth if there is one).
  2. Lean and height: the base's tilt under 0.5 degrees, its height 0.1527 m (the old rest height, within 1 mm).
  3. Clearances (mj_geomDistance between collision geoms, nothing touches): battery to the pedestal base box, the torso post to the pedestal plate and base, each arm's link1 to the pedestal
     plate (the arms hang beside the narrower pedestal), the arms to the battery. Printed, with a check that every one is positive.
"""

import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from src import robot_specs  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.simulator import RobotSimulator  # noqa: E402
from src.task_config import TASK_CFG  # noqa: E402

SCENE = PROJECT_ROOT / "models" / "scenes" / "chemistry_lab_combined.xml"
results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def _ancestors(m, b):
    while True:
        yield b
        if b == 0:
            return
        b = int(m.body_parentid[b])


def dist(m, d, ga, gb):
    fromto = np.zeros(6)
    return float(mujoco.mj_geomDistance(m, d, ga, gb, 1.0, fromto))


def main():
    sim = RobotSimulator(model_path=str(SCENE), cameras=None, pedestal_lift=robot_specs.PEDESTAL_SPECS, neck=True, battery=True, face=False)
    m, d = sim.model, sim.data
    ped = m.actuator(robot_specs.PEDESTAL_SPECS["actuator_name"]).id
    wheels = [m.actuator("left_motor").id, m.actuator("right_motor").id]
    base_dof = int(m.jnt_dofadr[m.joint("base_float").id])
    name = lambda g: m.geom(g).name or m.body(m.geom_bodyid[g]).name
    floor = m.geom("floor").id
    sphere_names = {m.geom(g).name for g in range(m.ngeom) if m.geom(g).name.startswith("contact_")}
    g_by_body = lambda b: [g for g in range(m.ngeom) if m.body(m.geom_bodyid[g]).name == b and (m.geom_contype[g] or m.geom_conaffinity[g])]
    for label, q in (("raised (the model's start)", robot_specs.PEDESTAL_SPECS["target_height"]), ("staging height", TASK_CFG["pedestal_q"])):
        mujoco.mj_resetData(m, d)
        d.qpos[0:7] = [-1.0, 3.5, 0.1527, 1.0, 0.0, 0.0, 0.0]               # in the open, away from the furniture
        d.qpos[m.joint('pedestal_joint').qposadr[0]] = q
        mujoco.mj_forward(m, d)
        ctrl = np.zeros(m.nu)
        ctrl[ped] = q
        for s in ("left", "right"):
            ctrl[arm_ids(m, s)["gripper"]] = 0.044
        for _ in range(int(3.0 * robot_specs.PHYSICS_HZ)):
            d.ctrl[:] = ctrl
            d.ctrl[wheels] = 0.0
            d.qvel[base_dof:base_dof + 2] = 0.0
            d.qvel[base_dof + 3:base_dof + 6] = 0.0
            mujoco.mj_step(m, d)
        print(f"\n{label}: pedestal command {q:.4f} m (joint {float(d.qpos[m.joint('pedestal_joint').qposadr[0]]):.4f})")
        robot_b = {b for b in range(m.nbody) if any(c == m.body("base_link").id for c in _ancestors(m, b))}
        in_robot = lambda g: int(m.geom_bodyid[g]) in robot_b
        pairs = {}
        for i in range(d.ncon):
            c = d.contact[i]
            key = tuple(sorted((name(c.geom1), name(c.geom2))))
            pairs[key] = (min(pairs.get(key, (1e9,))[0], float(c.dist)), in_robot(c.geom1), in_robot(c.geom2))
        floor_name = name(floor)
        other = {k: round(v[0], 5) for k, v in pairs.items() if (v[1] or v[2]) and not ((v[1] != v[2]) and floor_name in k and any(n in k for n in sphere_names))}
        print(f"  contacts: {sum(1 for v in pairs.values() if v[1] or v[2])} pairs involving the robot ({sum(1 for v in pairs.values() if v[1] != v[2]) - len(other)} floor with a base sphere; the scene's own furniture on the floor is not counted); others: {other if other else 'none'}")
        check(f"{label}: no contact other than the floor with the base spheres", not other)
        R = d.xmat[m.body("base_link").id].reshape(3, 3)
        tilt = math.degrees(math.acos(min(1.0, float(R[2, 2]))))
        check(f"{label}: tilt under 0.5 degrees", tilt < 0.5, f"{tilt:.3f} degrees")
        check(f"{label}: base height 0.1527 m within 1 mm", abs(d.qpos[2] - 0.1527) < 0.001, f"{d.qpos[2]:.4f} m")
        pairs_to_check = {"battery to pedestal base": ("battery", "pedestal_base"), "torso post to pedestal plate": ("openarm_body_link0", "pedestal_top"),
                          "torso post to pedestal base": ("openarm_body_link0", "pedestal_base"), "left link1 to pedestal plate": ("openarm_left_link1", "pedestal_top"),
                          "right link1 to pedestal plate": ("openarm_right_link1", "pedestal_top"), "left hand to battery": ("openarm_left_hand", "battery"),
                          "right hand to battery": ("openarm_right_hand", "battery"), "left link3 to battery": ("openarm_left_link3", "battery")}
        for lab, (a, b) in pairs_to_check.items():
            ga, gb = g_by_body(a), g_by_body(b)
            if not ga or not gb:
                continue
            dd = min(dist(m, d, x, y) for x in ga for y in gb)
            check(f"{label}: {lab} clearance is positive", dd > 0, f"{1000 * dd:.1f} mm")
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
